import{_ as e,c as d,o as a,a3 as r}from"./chunks/framework.BT-mtt1U.js";const p=JSON.parse('{"title":"Practical Exam","description":"","frontmatter":{"title":"Practical Exam"},"headers":[],"relativePath":"wiki/pr.md","filePath":"wiki/pr.md","lastUpdated":null}'),i={name:"wiki/pr.md"};function o(s,t,n,l,h,c){return a(),d("div",null,t[0]||(t[0]=[r('<h2 id="practical-exam" tabindex="-1">Practical Exam <a class="header-anchor" href="#practical-exam" aria-label="Permalink to &quot;Practical Exam&quot;">​</a></h2><ul><li>What happens in the practical exam?</li></ul><ol><li>Submission of practical file</li><li>Viva/oral</li><li>Activity/Answering the Paper</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Submission of practical file at the day of exam</strong></p></div><ul><li>Which subject has practical? Please view the table below:</li></ul><table tabindex="0"><thead><tr><th>S.No</th><th>Sr. Secondary (12th)</th><th>Secondary (10th)</th></tr></thead><tbody><tr><td>1</td><td>312 – Physics</td><td>211 – Mathematics</td></tr><tr><td>2</td><td>313 – Chemistry</td><td>212 – Science and Technology</td></tr><tr><td>3</td><td>314 – Biology</td><td>216 – Home Science</td></tr><tr><td>4</td><td>316 – Geography</td><td>225 – Painting</td></tr><tr><td>5</td><td>321 – Home Science</td><td>229 – Data Entry Operations</td></tr><tr><td>6</td><td>330 – Computer Science</td><td>230 – Indian Sign Language</td></tr><tr><td>7</td><td>332 – Painting</td><td>242 – Hindustani Sangeet</td></tr><tr><td>8</td><td>333 – Environmental Science</td><td>243 – Carnatic Sangeet</td></tr><tr><td>9</td><td>335 – Mass Communication</td><td>244 – Folk Art</td></tr><tr><td>10</td><td>336 – Data Entry Operations</td><td>256 – Bakery and Confectionery</td></tr><tr><td>11</td><td>339 – Library and Information Science</td><td>285 – Natyakala</td></tr><tr><td>12</td><td>356 – House-Keeping</td><td>605 – Cutting and Tailoring</td></tr><tr><td>13</td><td>357 – Catering Management</td><td>606 – Dress Making</td></tr><tr><td>14</td><td>358 – Food Processing</td><td>608 – Basic Computing</td></tr><tr><td>15</td><td>360 – Hotel Front Office Operations</td><td>612 – Beauty Culture and Hair Care</td></tr><tr><td>16</td><td>363 – Preservation of Fruits and Vegetables</td><td>613 – Desk Top Publishing</td></tr><tr><td>17</td><td>373 – Physical Education and Yog</td><td>614 – Yoga</td></tr><tr><td>18</td><td>376 – Early Childhood Care &amp; Education</td><td>628 – Indian Embroidery</td></tr><tr><td>19</td><td>385 – Natyakala</td><td>640 – Beauty Therapy</td></tr><tr><td>20</td><td>622 – Web Designing and Development</td><td>641 – Hair Care and Styling</td></tr><tr><td>21</td><td>631 – Computer &amp; Office Applications</td><td>642 – Hand and Foot Care</td></tr><tr><td>22</td><td>632 – Data Entry Operations</td><td>-</td></tr><tr><td>23</td><td>651 – IT Essentials: PC Hardware and Software</td><td>-</td></tr><tr><td>24</td><td>660 – Web Development</td><td>-</td></tr><tr><td>25</td><td>661 – CRM Domestic Voice</td><td>-</td></tr><tr><td>26</td><td>663 – Computer Hardware Assembly &amp; Maintenance</td><td>-</td></tr><tr><td>27</td><td>667 – Yoga Assistant</td><td>-</td></tr></tbody></table><hr><ul><li><a href="/wiki/howto-rec-book.html">How to make the practical file (Click to view)</a></li><li>What is FA? FA (formative assessment) also known as FA PCP carries <strong>50% of practical marks.</strong> In these classes they&#39;ll help with making practical file and explain what to do practical exam.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>FA is only for Stream 1 students only.</strong></p></div><p><strong>Exceptions</strong></p><p>a) NO FA PCP for stream 2, 3, and 4 meaning <strong>100%</strong> of marks are scored/given during Practical exam itself.</p><p>b) NO FA PCP <strong>marks</strong> for <a href="https://nios-students.pages.dev/wiki/FAQ&#39;S.html#what-is-the-two-vocational-sebjects-rule" target="_blank" rel="noreferrer">Vocational subjects</a> meaning <strong>100%</strong> of marks is Scored/given during Practical exam.</p><ul><li>What is SA? SA (Summative Assessment) also kown as practical exam here other <strong>50%</strong> of the marks are given/scored.</li></ul><p><strong>Exceptions</strong></p><p>a) For vocational subjects it&#39;s 100% cus no <strong>FA marks</strong></p><p>b) For stream 2, 3, and 4 <strong>100%</strong> of marks are scored/given during Practical exam.</p><ul><li>When is this?</li></ul><blockquote><p>[!WARRING] For streams 3 and 4 you have to ask your center. For stream 1 and 2 specific dates &amp; time aren&#39;t given. You have to visit the centre one or two days <strong>before the first exam</strong> e.g. If the first exam is on 20th you have to go 18th or 19th.</p></blockquote><h2 id="view-the-table-below" tabindex="-1">View the table below <a class="header-anchor" href="#view-the-table-below" aria-label="Permalink to &quot;View the table below&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sr. No.</th><th>Stream</th><th>Block</th><th>Month</th></tr></thead><tbody><tr><td>1</td><td>1</td><td>1 (Apr Exam)</td><td>March</td></tr><tr><td>2</td><td>1</td><td>2 (Oct Exam)</td><td>September</td></tr><tr><td>3</td><td>2</td><td>Same as &quot;stream-1 block-2 (Oct Exam)&quot;</td><td></td></tr><tr><td>4</td><td>3</td><td>Please ask your center on the day of theory paper</td><td>-</td></tr><tr><td>5</td><td>4</td><td>Please ask your center on the day of theory paper</td><td>-</td></tr></tbody></table><hr><ul><li>What are the marks for viva, flie, etc?</li></ul><h1 id="table-breaking-down-practical-marks-12th-sr-sec" tabindex="-1">Table breaking down practical marks (12th Sr.Sec): <a class="header-anchor" href="#table-breaking-down-practical-marks-12th-sr-sec" aria-label="Permalink to &quot;Table breaking down practical marks (12th Sr.Sec):&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Sr.No</th><th>sub code</th><th>File</th><th>Viva</th><th>Activities/Answering the Paper</th></tr></thead><tbody><tr><td>1</td><td>330</td><td>2¼</td><td>5</td><td>15</td></tr><tr><td>2</td><td>312,313,314,333,335,376 and others with 20 marks</td><td>2</td><td>3</td><td>7</td></tr><tr><td>3</td><td>332</td><td>6</td><td>10</td><td>20</td></tr><tr><td>4</td><td>336</td><td>5</td><td>5</td><td>25</td></tr><tr><td>5</td><td>663</td><td>10</td><td>10</td><td>50</td></tr><tr><td>6</td><td>660</td><td>10</td><td>10</td><td>10</td></tr><tr><td>7</td><td>622</td><td>5</td><td>5</td><td>5</td></tr><tr><td>8</td><td>373</td><td>3</td><td>5</td><td>10</td></tr></tbody></table><hr><table tabindex="0"><thead><tr><th>Sr.No</th><th>Sub code</th><th>Max Marks</th><th>FA</th><th>SA</th><th>Passing Marks</th></tr></thead><tbody><tr><td>1</td><td>330</td><td>40</td><td>20</td><td>20</td><td>13</td></tr><tr><td>2</td><td>312,313,314,333,335,376 and others with 20 marks</td><td>20</td><td>10</td><td>10</td><td>7</td></tr><tr><td>3</td><td>332 (NEW)</td><td>60</td><td>30</td><td>30</td><td>19</td></tr><tr><td>4</td><td>336</td><td>60</td><td>30</td><td>30</td><td>19</td></tr><tr><td>5</td><td>663</td><td>70</td><td>-</td><td>70</td><td>23</td></tr><tr><td>6</td><td>660</td><td>70</td><td>-</td><td>70</td><td>23</td></tr><tr><td>7</td><td>622</td><td>70</td><td>-</td><td>70</td><td>23</td></tr><tr><td>8</td><td>373</td><td>30</td><td>15</td><td>15</td><td>9</td></tr></tbody></table><h1 id="table-breaking-down-practical-marks-10th-sec" tabindex="-1">Table breaking down practical marks (10th Sec): <a class="header-anchor" href="#table-breaking-down-practical-marks-10th-sec" aria-label="Permalink to &quot;Table breaking down practical marks (10th Sec):&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Sr.No</th><th>Sub Code</th><th>Max Marks</th><th>FA</th><th>SA</th><th>Passing Marks</th></tr></thead><tbody><tr><td>1</td><td>211,212,216 and others (with 15 marks)</td><td>15</td><td>7½</td><td>7½</td><td>4</td></tr><tr><td>2</td><td>229</td><td>60</td><td>30</td><td>30</td><td>19</td></tr><tr><td>3</td><td>225</td><td>70</td><td>35</td><td>35</td><td>23</td></tr><tr><td>4</td><td>608</td><td>70</td><td>-</td><td>70</td><td>23</td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><table tabindex="0"><thead><tr><th>Sr.No</th><th>Sub Code</th><th>File</th><th>Viva</th><th>Activities/Answering the Paper</th></tr></thead><tbody><tr><td>1</td><td>211,212,216 and others (with 20 marks)</td><td>1½</td><td>2½</td><td>5</td></tr><tr><td>2</td><td>229</td><td>5</td><td>5</td><td>20</td></tr><tr><td>3</td><td>225</td><td>7</td><td>10</td><td>25</td></tr><tr><td>4</td><td>608</td><td>10</td><td>10</td><td>50</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>“Sub Code” is the subject code of the subject. The marks for submitting file comes under FA marks. In Secondary (10th) Passing in practical isn&#39;t required i.e. You need to get 33% of the maximum marks. It doesn&#39;t matter how you score these marks. For a example in science and tech you got 0 in TMA and practical but you got 33 or above in theory then you&#39;ll be considered passed. Here &#39;Passing marks&#39; are given for completeness. <a href="https://nios.ac.in/media/documents/notification/yr2024/Exam/PG_2024.pdf" target="_blank" rel="noreferrer">Source</a></strong></p></div><ul><li><p>What kind of questions will they ask in viva? Basic stuff regarding the subject like full forms, basic terms why did choose this subject etc...</p></li><li><p>Will they ask to perform activities/experiments? Probably not even if they do it would basic stuff.</p></li><li><p>What will come in the writen paper? They will ask any experiments in your lab manual. You have to write the whole thing. Mostly it&#39;s like this <em><strong>Write any two from the given four</strong></em></p></li></ul><h1 id="instructions-checklist" tabindex="-1">Instructions/Checklist <a class="header-anchor" href="#instructions-checklist" aria-label="Permalink to &quot;Instructions/Checklist&quot;">​</a></h1><p>[!NOTE]</p><blockquote><p>Go to the address given in the hallticket for specific time and date. The schedule should be displayed on there notice board or gate. <strong>One or Two day Before the first exam</strong><strong>What to bring (On the day of the exam</strong>)</p></blockquote><ol><li><a href="https://sdmis.nios.ac.in/registration/id-card" target="_blank" rel="noreferrer">ID card of NIOS</a></li><li>Pen and other stationary</li><li>ID Proof like aadhaar Card Passport or PAN card etc</li><li><a href="https://sdmis.nios.ac.in/search/hall-ticket" target="_blank" rel="noreferrer">Practical hallticket</a></li><li>Record Book/Practical file</li><li>Pad</li><li>Water bottle <em>remember to stay hydrated and chill!</em></li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>All the documents <strong>should in printed form</strong> <em>The hallticket is released one week before the first exam</em></p></div><h1 id="other-stuff" tabindex="-1">Other stuff <a class="header-anchor" href="#other-stuff" aria-label="Permalink to &quot;Other stuff&quot;">​</a></h1><ul><li>The time for all Subjects is <em><strong>3hrs</strong></em></li><li>Remember at fill your information correct on the answer sheet</li><li>Wear anything <strong>formal clothing</strong></li></ul><h1 id="view-assessment" tabindex="-1">View Assessment <a class="header-anchor" href="#view-assessment" aria-label="Permalink to &quot;View Assessment&quot;">​</a></h1><h2 id="what-is-this" tabindex="-1">What is this? <a class="header-anchor" href="#what-is-this" aria-label="Permalink to &quot;What is this?&quot;">​</a></h2><p>Firstly this <strong>ONLY FOR <a href="/wiki/Exams-Assignments.html">PE</a> students.</strong> You can whether your <a href="/wiki/Glossary.html#:~:text=AI/SC%3A Accredited Institutes/Study Centre">AI (Study Center)</a> has entered the practical marks or not. &quot;Marks Awarded&quot; &quot;Marks not awarded&quot; <strong>NOT ANY NUMBERS.</strong> It takes 1-2 weeks to update. <s>I know it&#39;s kinda pointless.</s></p><h1 id="how-to-check-it" tabindex="-1">How to check it? <a class="header-anchor" href="#how-to-check-it" aria-label="Permalink to &quot;How to check it?&quot;">​</a></h1><p><strong>Step 1</strong> Go to <a href="https://exams.nios.ac.in/auth/view-student-formative-assessment" target="_blank" rel="noreferrer">https://exams.nios.ac.in/auth/view-student-formative-assessment</a> (Ignore what is written on the URL)</p><p><strong>Step 2</strong> Enter your enrollment number and DOB and chose “<strong>summative assessment</strong>”</p><p><strong>Step 3</strong> View it!</p><p>Here&#39;s example of how it looks: <img src="https://cdn.jsdelivr.net/gh/nios-students/docs@master/wiki/assets/sa.jpg" alt="SA" width="400"></p><p>The marks will show on the marksheet: <img src="https://cdn.jsdelivr.net/gh/nios-students/docs@master/wiki/assets/ms.jpg" alt="Marksheet" width="400"></p><hr><p>Any questions? <a href="https://www.reddit.com/r/Nios_unofficial/comments/1jk4nm2/comment/mx5ljcg/?context=3" target="_blank" rel="noreferrer">Past XP</a> or <a href="https://www.reddit.com/r/Nios_unofficial/" target="_blank" rel="noreferrer">Ask here</a> or <a href="mailto:unofficialnios@gmail.com" target="_blank" rel="noreferrer">e-mail</a> | <strong>Research and Written by pingforhelp</strong></p>',50)]))}const u=e(i,[["render",o]]);export{p as __pageData,u as default};
